import fs from 'node:fs';
import {resolveAccountBuildConfig} from './account-build-config.mjs';

const config = resolveAccountBuildConfig(process.env.ASMB_ACCOUNT_CONFIG ?? 'offline');
fs.mkdirSync(new URL('./dist-host/', import.meta.url), {recursive: true});
// Literal exports seal the build-time choice. Packaged startup never reads an
// environment variable or a user-selected configuration path.
fs.writeFileSync(new URL('./dist-host/account-config.mjs', import.meta.url),
  '// Generated by build-account-config.mjs. Public identifiers only.\n' +
  `export const applicationAccount = ${JSON.stringify(config.applicationAccount)};\n` +
  `export const githubApp = ${JSON.stringify(config.githubApp)};\n` +
  `export const accountConfiguration = ${JSON.stringify({id: config.id, sha256: config.sha256})};\n`);
console.log(`Account build configuration: ${config.id} (${config.sha256})`);
